<?php
require_once __DIR__.'/legacy_operational_corrections.php';
function lop_bank_actor(mysqli $db,int $actor,int $unit,bool $lock=false): array {
    if(!in_array($unit,[1,2,3],true)||(int)$db->query('SELECT current_unit_id()')->fetch_row()[0]!==$unit)throw new DomainException('Pilih unit untuk transaksi.',409);
    $a=lf_one($db,'SELECT id,role,unit_id,is_active,username FROM admin WHERE id=?'.($lock?' FOR UPDATE':''),[$actor]);if(!$a||!$a['is_active']||!in_array($a['role'],['super_admin','admin','kasir'],true)||($a['role']!=='super_admin'&&$a['unit_id']!==null&&(int)$a['unit_id']!==$unit))throw new DomainException('Hak transaksi rekening tidak tersedia.',403);return $a;
}
function lop_bank_new(mysqli $db,int $actor,int $unit,int $ownerId,array $input,string $key): array {
    lop_require($db);if(!preg_match('/^[a-f0-9]{64}$/D',$key))throw new DomainException('Kunci transaksi tidak valid.');$amount=lf_cents($input['amount']??null);$direction=$input['direction']??'';if($amount<=0||!in_array($direction,['in','out'],true))throw new DomainException('Isi nominal positif dan arah transaksi.');$date=lop_date($input['date']??null);$note=trim((string)($input['note']??''));if(!$date||$date>date('Y-m-d H:i:s')||mb_strlen($note)>1000)throw new DomainException('Tanggal atau catatan tidak valid.');
    $requestDigest=hash('sha256',lf_json([$ownerId,$amount,$direction,$date,$note]));$db->query('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$db->begin_transaction();try{$accountActor=lop_bank_actor($db,$actor,$unit,true);$existing=lf_one($db,'SELECT entity_type,entity_id,actor_id,after_data FROM legacy_op_audit WHERE request_key=? FOR UPDATE',[$key]);if($existing){if((int)$existing['actor_id']!==$actor||$existing['entity_type']!=='bank_new'||(json_decode($existing['after_data'],true)['request_digest']??'')!==$requestDigest)throw new DomainException('Kunci sudah digunakan.');$db->commit();return ['id'=>(int)$existing['entity_id'],'replayed'=>true];}
        $target=lf_one($db,'SELECT batch_id FROM legacy_op_owners WHERE id=?',[$ownerId]);if(!$target)throw new DomainException('Rekening tidak ditemukan.');lf_one($db,'SELECT id FROM legacy_full_batches WHERE id=? FOR UPDATE',[$target['batch_id']]);$owner=lf_one($db,"SELECT o.*,b.cutoff FROM legacy_op_owners o JOIN legacy_full_batches b ON b.id=o.batch_id AND b.unit_id=o.unit_id WHERE o.id=? AND o.state='ready' AND b.state='completed' FOR UPDATE",[$ownerId]);if(!$owner||$owner['student_id'])throw new DomainException('Gunakan alur tabungan siswa untuk rekening siswa.');if($date<$owner['cutoff'])throw new DomainException('Tanggal mendahului peralihan.');$account=lf_one($db,'SELECT * FROM legacy_op_accounts WHERE owner_id=? FOR UPDATE',[$ownerId]);if(!$account)throw new DomainException('Saldo sumber rekening belum direkonsiliasi.');$balance=lf_cents($account['balance'])+($direction==='in'?$amount:-$amount);if($balance<0)throw new DomainException('Saldo tidak mencukupi.');
        lf_query($db,"INSERT INTO legacy_op_journals(unit_id,batch_id,owner_id,row_key,source_operator,source_date,incoming,outgoing,origin,note) VALUES(?,?,?,?,?,?,?,?,'new',?)",[$unit,$owner['batch_id'],$ownerId,hash('sha256','new:'.$key),$accountActor['username'],$date,$direction==='in'?lf_money($amount):'0.00',$direction==='out'?lf_money($amount):'0.00',$note]);$journal=(int)$db->insert_id;
        lf_query($db,'UPDATE legacy_op_accounts SET balance=?,version=version+1 WHERE id=?',[lf_money($balance),$account['id']]);lf_query($db,"INSERT INTO legacy_op_audit(unit_id,actor_id,entity_type,entity_id,request_key,reason,before_data,after_data) VALUES(?,?,'bank_new',?,?,?,?,?)",[$unit,$actor,$journal,$key,$note?:'Transaksi tabungan baru',$account?lf_json($account):'{}',lf_json(['balance'=>lf_money($balance),'journal_id'=>$journal,'request_digest'=>$requestDigest])]);
        $b=lf_one($db,'SELECT manifest FROM legacy_full_batches WHERE id=? FOR UPDATE',[$owner['batch_id']]);$m=json_decode($b['manifest'],true);$m['working_digest']=lop_working_digest($db,$owner['batch_id']);lf_query($db,'UPDATE legacy_full_batches SET manifest=? WHERE id=?',[lf_json($m),$owner['batch_id']]);$db->commit();return ['id'=>$journal,'replayed'=>false];
    }catch(Throwable $e){$db->rollback();throw $e;}
}
